-- create "shop_applications" table
CREATE TABLE "shop_applications" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "status" character varying(24) NOT NULL DEFAULT 'pending_verification', "email" character varying(254) NOT NULL, "email_verified_at" timestamptz NULL, "contact_name" character varying(100) NOT NULL, "phone" character varying(20) NOT NULL DEFAULT '', "shop_name" character varying(100) NOT NULL, "business_summary" text NOT NULL, "consent_version" character varying(32) NOT NULL, "consented_at" timestamptz NOT NULL, "risk_flags" jsonb NULL, "submitted_ip_hmac" character varying(64) NOT NULL DEFAULT '', "reviewed_by" bigint NULL, "reviewed_at" timestamptz NULL, "decision_reason" text NOT NULL DEFAULT '', "internal_note" text NOT NULL DEFAULT '', "provisioned_shop_id" bigint NULL, "purged_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "shop_applications_status_check" CHECK ((status)::text = ANY ((ARRAY['pending_verification'::character varying, 'pending_review'::character varying, 'approved'::character varying, 'rejected'::character varying, 'expired'::character varying, 'withdrawn'::character varying])::text[])));
-- create index "shop_applications_provisioned_shop_id_key" to table: "shop_applications"
CREATE UNIQUE INDEX "shop_applications_provisioned_shop_id_key" ON "shop_applications" ("provisioned_shop_id");
-- create index "shopapplication_email_open_key" to table: "shop_applications"
CREATE UNIQUE INDEX "shopapplication_email_open_key" ON "shop_applications" ("email") WHERE ((status)::text = ANY ((ARRAY['pending_verification'::character varying, 'pending_review'::character varying])::text[]));
-- create index "shopapplication_email_status" to table: "shop_applications"
CREATE INDEX "shopapplication_email_status" ON "shop_applications" ("email", "status");
-- create index "shopapplication_status_created_at" to table: "shop_applications"
CREATE INDEX "shopapplication_status_created_at" ON "shop_applications" ("status", "created_at");
-- create "shop_application_events" table
CREATE TABLE "shop_application_events" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "application_id" bigint NOT NULL, "actor_user_id" bigint NULL, "event" character varying(32) NOT NULL, "detail" jsonb NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "shop_application_events_event_check" CHECK ((event)::text = ANY ((ARRAY['submitted'::character varying, 'verification_sent'::character varying, 'verified'::character varying, 'verified_manually'::character varying, 'approved'::character varying, 'approve_failed'::character varying, 'rejected'::character varying, 'note'::character varying, 'message_marked_sent'::character varying, 'expired'::character varying, 'purged'::character varying])::text[])));
-- create index "shopapplicationevent_application_id_id" to table: "shop_application_events"
CREATE INDEX "shopapplicationevent_application_id_id" ON "shop_application_events" ("application_id", "id");
-- create "shop_application_messages" table
CREATE TABLE "shop_application_messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" character varying(24) NOT NULL, "recipient_email" character varying(254) NOT NULL, "subject" character varying(200) NOT NULL, "body_text" text NOT NULL, "delivery" character varying(8) NOT NULL, "status" character varying(16) NOT NULL, "error_reason" character varying(200) NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "sent_at" timestamptz NULL, "marked_by" bigint NULL, "application_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "shop_application_messages_shop_applications_application" FOREIGN KEY ("application_id") REFERENCES "shop_applications" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "shop_application_messages_delivery_check" CHECK ((delivery)::text = ANY ((ARRAY['manual'::character varying, 'email'::character varying])::text[])), CONSTRAINT "shop_application_messages_kind_check" CHECK ((kind)::text = ANY ((ARRAY['verify_email'::character varying, 'approved'::character varying, 'rejected'::character varying])::text[])), CONSTRAINT "shop_application_messages_status_check" CHECK ((status)::text = ANY ((ARRAY['pending_manual'::character varying, 'queued'::character varying, 'sent'::character varying, 'failed'::character varying])::text[])));
-- create index "shopapplicationmessage_application_id_id" to table: "shop_application_messages"
CREATE INDEX "shopapplicationmessage_application_id_id" ON "shop_application_messages" ("application_id", "id");
-- create index "shopapplicationmessage_status_id" to table: "shop_application_messages"
CREATE INDEX "shopapplicationmessage_status_id" ON "shop_application_messages" ("status", "id");
-- create "shop_application_tokens" table
CREATE TABLE "shop_application_tokens" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "token_hash" character varying(64) NOT NULL, "expires_at" timestamptz NOT NULL, "used_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "application_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "shop_application_tokens_shop_applications_application" FOREIGN KEY ("application_id") REFERENCES "shop_applications" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- create index "shop_application_tokens_token_hash_key" to table: "shop_application_tokens"
CREATE UNIQUE INDEX "shop_application_tokens_token_hash_key" ON "shop_application_tokens" ("token_hash");
-- create index "shopapplicationtoken_application_id_created_at" to table: "shop_application_tokens"
CREATE INDEX "shopapplicationtoken_application_id_created_at" ON "shop_application_tokens" ("application_id", "created_at");
